function check(input, actual, expected) {
  const [n, edges, source, destination, target] = input;
  if (!Array.isArray(actual) || !Array.isArray(expected)) return false;
  if (expected.length === 0) return actual.length === 0;
  if (actual.length !== edges.length) return false;
  const original = new Map();
  for (const [a, b, w] of edges) original.set(Math.min(a, b) * n + Math.max(a, b), w);
  const seen = new Set();
  const graph = Array.from({ length: n }, () => []);
  for (const edge of actual) {
    if (!Array.isArray(edge) || edge.length !== 3) return false;
    const [a, b, w] = edge;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return false;
    const key = Math.min(a, b) * n + Math.max(a, b);
    if (!original.has(key) || seen.has(key)) return false;
    seen.add(key);
    if (!Number.isInteger(w) || w < 1 || w > 2000000000) return false;
    if (original.get(key) !== -1 && original.get(key) !== w) return false;
    graph[a].push([b, w]);
    graph[b].push([a, w]);
  }
  const dist = new Array(n).fill(Infinity);
  const done = new Array(n).fill(false);
  dist[source] = 0;
  for (let round = 0; round < n; round++) {
    let node = -1;
    for (let v = 0; v < n; v++) if (!done[v] && (node === -1 || dist[v] < dist[node])) node = v;
    done[node] = true;
    for (const [next, w] of graph[node]) dist[next] = Math.min(dist[next], dist[node] + w);
  }
  return dist[destination] === target;
}

