function validate([n, edges, source, destination, target]) {
  if (!Number.isInteger(n) || n < 1 || n > 100) return 'n is between 1 and 100.';
  if (!Array.isArray(edges) || edges.length < 1 || edges.length > n * (n - 1) / 2) return 'edges needs 1 to n * (n - 1) / 2 edges.';
  if (!Number.isInteger(source) || !Number.isInteger(destination) || source < 0 || destination < 0 || source >= n || destination >= n) return 'source and destination must be nodes of the graph.';
  if (source === destination) return 'source and destination must be different.';
  if (!Number.isInteger(target) || target < 1 || target > 1000000000) return 'target is between 1 and 10^9.';
  const parent = Array.from({ length: n }, (_, i) => i);
  const find = (x) => { while (parent[x] !== x) { parent[x] = parent[parent[x]]; x = parent[x]; } return x; };
  const seen = new Set();
  let parts = n;
  for (const edge of edges) {
    if (!Array.isArray(edge) || edge.length !== 3) return 'Each edge is [a, b, w].';
    const [a, b, w] = edge;
    if (!Number.isInteger(a) || !Number.isInteger(b) || a < 0 || b < 0 || a >= n || b >= n) return 'Edge ends must be nodes 0 to n - 1.';
    if (a === b) return 'An edge cannot join a node to itself.';
    if (!Number.isInteger(w) || (w !== -1 && (w < 1 || w > 10000000))) return 'Each weight is -1 or between 1 and 10^7.';
    const key = Math.min(a, b) * n + Math.max(a, b);
    if (seen.has(key)) return 'Two nodes can be joined by at most one edge.';
    seen.add(key);
    const ra = find(a), rb = find(b);
    if (ra !== rb) { parent[ra] = rb; parts--; }
  }
  if (parts !== 1) return 'The graph must be connected.';
  return null;
}

