function modifiedGraphEdges(n, edges, source, destination, target) {
  const graph = Array.from({ length: n }, () => []);
  for (let id = 0; id < edges.length; id++) {
    const [a, b] = edges[id];
    graph[a].push([b, id]);
    graph[b].push([a, id]);
  }

  const shortest = (base, extra) => {
    const dist = new Array(n).fill(Infinity);
    const done = new Array(n).fill(false);
    dist[source] = 0;
    for (let round = 0; round < n; round++) {
      let node = -1;
      for (let v = 0; v < n; v++) {
        if (!done[v] && (node === -1 || dist[v] < dist[node])) {
          node = v;
        }
      }
      done[node] = true;
      for (const [next, id] of graph[node]) {
        let weight = edges[id][2];
        if (weight === -1) {
          weight = 1;
          if (base !== null) {
            weight = Math.max(1, base[next] + extra - dist[node]);
            edges[id][2] = weight;
          }
        }
        dist[next] = Math.min(dist[next], dist[node] + weight);
      }
    }
    return dist;
  };

  const first = shortest(null, 0);
  if (first[destination] > target) {
    return [];
  }
  const delta = target - first[destination];
  const second = shortest(first, delta);
  if (second[destination] !== target) {
    return [];
  }
  return edges;
}

