function generate(rand, size) {
  const pick = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  const large = size === 'large';
  const n = large ? pick(60, 100) : pick(2, 6);
  const maxEdges = n * (n - 1) / 2;
  const m = large ? Math.min(maxEdges, pick(n - 1, 2000)) : pick(n - 1, maxEdges);
  const openShare = [0, 0.2, 0.5, 0.8, 1][pick(0, 4)];
  const maxW = large ? (rand() < 0.5 ? 10000000 : 1000) : pick(1, 10);
  const used = new Set();
  const edges = [];
  const add = (a, b) => {
    const key = Math.min(a, b) * n + Math.max(a, b);
    if (a === b || used.has(key)) return;
    used.add(key);
    edges.push([a, b, rand() < openShare ? -1 : pick(1, maxW)]);
  };
  const order = Array.from({ length: n }, (_, i) => i);
  for (let i = n - 1; i > 0; i--) { const j = pick(0, i); [order[i], order[j]] = [order[j], order[i]]; }
  for (let i = 1; i < n; i++) add(order[i], order[pick(0, i - 1)]);
  while (edges.length < m) add(pick(0, n - 1), pick(0, n - 1));
  for (let i = edges.length - 1; i > 0; i--) { const j = pick(0, i); [edges[i], edges[j]] = [edges[j], edges[i]]; }
  const source = pick(0, n - 1);
  let destination = pick(0, n - 2);
  if (destination >= source) destination++;
  const distance = (openWeight) => {
    const d = new Array(n).fill(Infinity);
    d[source] = 0;
    for (let k = 0; k < n; k++) {
      let changed = false;
      for (const [a, b, w0] of edges) {
        const w = w0 === -1 ? openWeight : w0;
        if (d[a] + w < d[b]) { d[b] = d[a] + w; changed = true; }
        if (d[b] + w < d[a]) { d[a] = d[b] + w; changed = true; }
      }
      if (!changed) break;
    }
    return d[destination];
  };
  const low = distance(1);
  const high = Math.min(distance(Infinity), 1000000000);
  let target;
  const mode = rand();
  if (low <= high && mode < 0.6) target = pick(low, high);
  else if (low <= high && mode < 0.7) target = low;
  else if (low <= high && mode < 0.8) target = high;
  else target = large ? pick(1, rand() < 0.5 ? 1000000000 : Math.max(1, 2 * low)) : pick(1, 25);
  return [n, edges, source, destination, Math.max(1, target)];
}
